// The product n * psi(n) is maximized when both n and psi(n) are large.
// Since psi(n) = (10^d - 1) - n for a d-digit number n (where d is the number of digits),
// we have n * psi(n) = n * ((10^d - 1) - n).
// This is a quadratic function in n: f(n) = n * (10^d - 1) - n^2.
// This is a downward parabola with maximum at n = (10^d - 1) / 2.
// So for each digit length d, the maximum is near the middle of the range of d-digit numbers.
// But we need to consider the intersection with [l, r].

// Let's collect candidate points:
// 1. l and r
// 2. For each digit length d that intersects [l, r], the point closest to (10^d - 1)/2 within the valid range for that digit length and within [l, r].

$candidates = [];
$candidates[] = $l;
$candidates[] = $r;

// Determine the range of digit lengths
$dMin = strlen((string)$l);
$dMax = strlen((string)$r);

for ($d = $dMin; $d <= $dMax; $d++) {
    $low = (int)pow(10, $d - 1);
    $high = (int)pow(10, $d) - 1;

    // Intersect with [l, r]
    $start = max($low, $l);
    $end = min($high, $r);

    if ($start > $end) {
        continue;
    }

    // The optimal point for this digit length is at (10^d - 1) / 2
    $optimal = (int)floor((pow(10, $d) - 1) / 2);

    // Check candidates around the optimal point within [start, end]
    // The parabola is symmetric, so we check the optimal point and its neighbors
    $candidates[] = $optimal;
    $candidates[] = $optimal - 1;
    $candidates[] = $optimal + 1;

    // Also check the boundaries of the intersection
    $candidates[] = $start;
    $candidates[] = $end;
}

// Filter candidates to be within [l, r] and positive
$candidates = array_unique($candidates);
$maxWeight = 0;
foreach ($candidates as $c) {
    if ($c >= $l && $c <= $r && $c > 0) {
        $w = weight($c);
        if ($w > $maxWeight) {
            $maxWeight = $w;
        }
    }
}

echo $maxWeight . "\n";
